    [5821] = {
        achievementId = 5821,
        name = "Death from Above",
        category = "Raids",
        sourceType = "Achievement",
        source = "Death from Above",
        difficulty = "easy",
        difficultyReason = "Leave ground-level Cinderweb Drones alive while killing Beth'tilac.",
        acquisition = "Difficulty: Easy - Leave ground-level Cinderweb Drones alive while killing Beth'tilac.\n\n1. Enter Firelands and reach Beth'tilac's western lair. Start the encounter and kill ONE hanging Cinderweb Spinner, then click its dropped web strand to climb onto the canopy. Spinners are different from the large ground-level Drones.\n\n2. Damage Beth'tilac upstairs and follow her down if she transitions. Use single-target attacks and keep Cinderweb Drones alive on the lower floor; killing no drones at all satisfies the condition.\n\n3. If deliberately killing a Drone, wait until its energy is exhausted and it climbs onto the canopy, then kill it while it is still upstairs. The simplest high-level route is to ignore drones entirely and finish Beth'tilac without a ground-level drone death.",
