    [5827] = {
        achievementId = 5827,
        name = "Avengers of Hyjal",
        category = "Reputation",
        sourceType = "Achievement",
        source = "Avengers of Hyjal",
        difficulty = "medium",
        difficultyReason = "Repeated Firelands boss kills; the final reputation point needs care.",
        acquisition = "Difficulty: Medium - Repeated Firelands boss kills; the final reputation point needs care.\n\n1. Enter original Firelands from Mount Hyjal (47.2, 78.1). This is the AVENGERS of Hyjal raid faction. Sanctuary of Malorne and Molten Front dailies instead award Guardians of Hyjal reputation.\n\n2. Kill and loot the raid's trash before clearing bosses. Ordinary trash stops awarding reputation at 5,999/6,000 Friendly. Larger eligible creatures such as Molten Lords, Ancient Core Hounds and harder inner trash can continue toward 11,999/12,000 Honored.\n\n3. Once trash no longer advances the bar, clear Firelands bosses: Shannox, Beth'tilac, Rhyolith, Alysrazor, Baleroc, Staghelm and Ragnaros. Use HEROIC for the stronger boss reputation and final point. Run each eligible Normal/Heroic lockout after weekly resets; changing the old 10/25 selector is not extra loot or reputation.\n\n4. At 20,999/21,000 Revered, kill a HEROIC boss to cross into Exalted. If solo credit still sticks there, a September 2026 comment reports that support's working fix was to enter in a raid with one other player and kill a boss together. Verify the final point rather than continuing an ineffective trash farm.\n\n5. Confirm Exalted and the Avengers of Hyjal achievement/title. A tabard does not grant this reputation from unrelated dungeons, and Molten Front daily progress does not substitute for Firelands kills.",
        stepCount = 5,
        waypoints = {
            {
                mapID = 198,
                x = 0.47200000000000003,
                y = 0.7809999999999999,
                step = 1,
