    [5830] = {
        achievementId = 5830,
        name = "Share the Pain",
        category = "Raids",
        sourceType = "Achievement",
        source = "Share the Pain",
        difficulty = "easy",
        difficultyReason = "Finish Baleroc before anyone receives Torment on more than three separate occasions.",
        acquisition = "Difficulty: Easy - Finish Baleroc before anyone receives Torment on more than three separate occasions.\n\n1. Enter Firelands, clear Baleroc's approach and kill him directly at high level. There is no need to wait for a crystal if your damage ends the encounter first.\n\n2. If a longer fight produces Shards of Torment, rotate the soakers so no player receives Torment more than THREE separate times. This counts applications or soaks, not the number of damage stacks within one continuous soak.\n\n3. Keep other players away from crystal range when they are not assigned, then finish Baleroc and check the achievement. A high-level solo kill can complete it without any crystal rotation.",
