    [5850] = {
        achievementId = 5850,
        name = "Fish or Cut Bait: Undercity",
        category = "Professions",
        sourceType = "Achievement",
        source = "Fish or Cut Bait: Undercity",
        difficulty = "medium",
        difficultyReason = "Five easy quests on a rotating daily schedule; the last variant can take many resets.",
        acquisition = "Difficulty: Medium - Five easy quests on a rotating daily schedule; the last variant can take many resets.\n\n1. If Undercity is blighted or its NPCs are absent, ask Zidormi in Tirisfal Glades at 69.4, 62.8 for the time before the battle, then enter original Undercity. Learn basic Fishing and visit Armand Cromwell at the marked city location. Enable Trivial Quests. Check that you have not already accepted or completed a capital Fishing daily elsewhere today.\n\n2. Track this achievement and compare today's offered quest with the five required variants: Fish Head; Like Pike?; Moat Monster!; Tadpole Terror; Time for Slime. Check other cities before accepting if you want to spend today's shared daily slot on a missing criterion elsewhere.\n\n3. Accept the missing variant, follow its quest items and marked local objectives, then RETURN to Armand Cromwell and turn it in. Collecting its materials without the hand-in does not complete the criterion. Keep the supplied bait, lure or container until that quest is finished.\n\n4. Return after daily resets until all five DIFFERENT variants are checked. Repeating one daily five times does not complete the achievement. You can do only one capital Cooking daily and one capital Fishing daily per character per day, across all three same-faction cities; Shattrath and Northrend Dalaran have separate dailies.\n\n5. If no quest is visible, check your quest log for another city's accepted daily, today's completion and the correct city phase before assuming the achievement is removed. Random repeats are expected and skipping a quest does not force the missing one tomorrow.",
        stepCount = 5,
        waypoints = {
            { mapID = 90, x = 0.804, y = 0.316, step = 1, label = "Armand Cromwell - Fishing daily giver" },
            { mapID = 90, x = 0.804, y = 0.316, step = 3, label = "Armand Cromwell - turn in for criterion credit" },
