    [5859] = {
        achievementId = 5859,
        name = "Legacy of Leyara",
        category = "Quests",
        sourceType = "Achievement",
        source = "Legacy of Leyara",
        difficulty = "medium",
        difficultyReason = "Complete the campaign unlocks and Leyara's final scripted confrontation.",
        acquisition = "Difficulty: Medium - Complete the campaign unlocks and Leyara's final scripted confrontation.\n\n1. Finish Mount Hyjal through Aessina's Miracle, then begin the Sanctuary of Malorne's Regrowth/Molten Front introduction. Enable Trivial Quests. Complete The Sanctuary Must Not Fall, collect 20 Marks of the World Tree for Calling for Reinforcements, and follow Through the Gates of Hell into the Molten Front. The portal is at 27.6,56.3 in Hyjal.\n\n2. Finish Leyara's confrontation with Hamuul during the Sanctuary storyline. Continue the Front on this character, recruiting BOTH Shadow Wardens and Druids of the Talon for 150 marks each. These are successive unlocks; the first recruitment does not permanently exclude the other.\n\n3. Spend another 125 marks on Filling the Moonwell and complete its follow-up. This unlocks Into the Depths; the other two 125-mark projects are needed for the full Offensive achievement, but not this particular Leyara finale.\n\n4. Accept Into the Depths from Malfurion at Malfurion's Breach. Enter the Igneous Depths and continue to Leyara's underground chamber around 64.4,59.0. Fight her and let the Malfurion/Hamuul sequence finish, then turn the quest in to Malfurion. Check the three Leyara-story criteria.\n\n5. The later Smoke-Stained Locket mail and Moonglade memory quests award Leyara's Locket, a separate toy. Do not mistake possession of that quest starter, a Firelands raid kill, or unlocking a vendor alone for completing Into the Depths.",
        stepCount = 5,
        waypoints = {
            { mapID = 198, x = 0.271, y = 0.625, step = 1, label = "Sanctuary of Malorne - unlocks and daily quests" },
            { mapID = 338, x = 0.47, y = 0.907, step = 2, label = "Malfurion's Breach - campaign hub" },
            { mapID = 198, x = 0.271, y = 0.625, step = 3, label = "Matoclaw - Filling the Moonwell" },
            { mapID = 338, x = 0.47, y = 0.907, step = 4, label = "Malfurion - Into the Depths" },
            { mapID = 338, x = 0.644, y = 0.59, step = 4, label = "Leyara - underground Igneous Depths" },
        },
        sources = {
