    [5861] = {
        achievementId = 5861,
        name = "The Fiery Lords of Sethria's Roost",
        category = "Quests",
        sourceType = "Achievement",
        source = "The Fiery Lords of Sethria's Roost",
        difficulty = "medium",
        difficultyReason = "Four linked outdoor elites, with a flying patrol and variable spawn delays.",
        acquisition = "Difficulty: Medium - Four linked outdoor elites, with a flying patrol and variable spawn delays.\n\n1. Finish Mount Hyjal through Aessina's Miracle, then begin the Sanctuary of Malorne's Regrowth/Molten Front introduction. Enable Trivial Quests. Complete The Sanctuary Must Not Fall, collect 20 Marks of the World Tree for Calling for Reinforcements, and follow Through the Gates of Hell into the Molten Front. The portal is at 27.6,56.3 in Hyjal.\n\n2. Go south through ALL the terraces of Sethria's Roost. Search for Kelbnar near 30.5,81.0, Fah Jarakk near 30.9,86.8 and Searris near 32.4,95.7. Look for yellow/neutral nameplates as well as red ones; stopping at the first ledge misses the lower spawn areas.\n\n3. Look UP for Andrazor, the firehawk patrolling above the terraces, including around 31.2,84.4. Use a ranged pull when the patrol comes within reach. Kill each of the four named elites and check its individual criterion.\n\n4. After each kill, search the other terraces again. The spawns are linked, but their order and delay are not a guaranteed fixed circuit; other players may already have killed part of the group. Wait and recheck missing names rather than killing ordinary Fiery Behemoths and expecting credit.",
        stepCount = 4,
        waypoints = {
            { mapID = 198, x = 0.271, y = 0.625, step = 1, label = "Sanctuary of Malorne - unlocks and daily quests" },
