    [5862] = {
        achievementId = 5862,
        name = "Ludicrous Speed",
        category = "Quests",
        sourceType = "Achievement",
        source = "Ludicrous Speed",
        difficulty = "medium",
        difficultyReason = "Keep a short-lived Soar stack alive while collecting birds in the quest vehicle.",
        acquisition = "Difficulty: Medium - Keep a short-lived Soar stack alive while collecting birds in the quest vehicle.\n\n1. Finish Mount Hyjal through Aessina's Miracle, then begin the Sanctuary of Malorne's Regrowth/Molten Front introduction. Enable Trivial Quests. Complete The Sanctuary Must Not Fall, collect 20 Marks of the World Tree for Calling for Reinforcements, and follow Through the Gates of Hell into the Molten Front. The portal is at 27.6,56.3 in Hyjal.\n\n2. When Matoclaw offers Call the Flock, accept it and use the provided feather to enter the bird/harpy vehicle. Fly into the Regrowth and locate Goldwing Hawks, Forest Owls and Alpine Songbirds before starting your collection circuit.\n\n3. Use the vehicle's call close to the birds. Goldwing Hawks add FIFTEEN Soar stacks, owls FIVE and songbirds ONE. Collect the next bird before the short Soar timer expires; the flock still visible behind you does not prove that the buff remains active.\n\n4. A straightforward current-comment method is to activate the vehicle, abandon Call the Flock while STAYING in the vehicle, and collect further hawks/owls without the quest's per-species cap. This is confirmed by February and June 2026 comments. Keep moving between nearby respawns until the actual Soar buff reaches at least SIXTY-FIVE.\n\n5. Alternatively, complete Call the Flock, remain in the form for Wings Aflame, and continue calling birds before leaving the vehicle. Check credit before dismissing the form. Reaccept the abandoned daily afterward if you still want its marks.",
        stepCount = 5,
        waypoints = { { mapID = 198, x = 0.271, y = 0.625, step = 1, label = "Sanctuary of Malorne - unlocks and daily quests" } },
