    [5869] = {
        achievementId = 5869,
        name = "Infernal Ambassadors",
        category = "Quests",
        sourceType = "Achievement",
        source = "Infernal Ambassadors",
        difficulty = "medium",
        difficultyReason = "Daily boss variants; Galenges must receive exactly the first weakening before the kill.",
        acquisition = "Difficulty: Medium - Daily boss variants; Galenges must receive exactly the first weakening before the kill.\n\n1. Finish Mount Hyjal through Aessina's Miracle, then begin the Sanctuary of Malorne's Regrowth/Molten Front introduction. Enable Trivial Quests. Complete The Sanctuary Must Not Fall, collect 20 Marks of the World Tree for Calling for Reinforcements, and follow Through the Gates of Hell into the Molten Front. The portal is at 27.6,56.3 in Hyjal.\n\n2. Finish each offered Regrowth daily to unlock its boss follow-up. Use your own quest summon where possible and keep the summoning item until the criterion is complete. Missing bosses require another day's daily variant.\n\n3. NEMESIS / Echoes of Nemesis: summon through Tooga. Kill without taking the eruption; if it is cast, stand beneath Tooga's protective shell. MILLAGAZOR / Wings Aflame: keep moving out of the Gout of Flame ground eruption, then finish her encounter.\n\n4. LYLAGAR / The Call of the Pack: move out of his frontal breath before it finishes. PYRACHNIS / Nature's Blessing: use the emerald to summon, then kill without using it to cleanse her poison. High-level quick kills can satisfy these avoidance conditions.\n\n5. GALENGES / The Power of Malorne: summon with the quest staff and STOP damage. Let Malorne's spirit weaken him ONCE, confirm the debuff, then kill him before a SECOND weakening. An instant kill before the FIRST weakening does not qualify.\n\n6. If a criterion fails, use the summoning item again while the quest remains active and retry correctly. Check all five criteria; ordinary quest completion alone does not prove that its special condition was met.",
        stepCount = 6,
        waypoints = { { mapID = 198, x = 0.271, y = 0.625, step = 1, label = "Sanctuary of Malorne - unlocks and daily quests" } },
        areaMaps = { 198 },
