    [5870] = {
        achievementId = 5870,
        name = "Fireside Chat",
        category = "Quests",
        sourceType = "Achievement",
        source = "Fireside Chat",
        difficulty = "medium",
        difficultyReason = "Eight conversations spread across both campaign branches.",
        acquisition = "Difficulty: Medium - Eight conversations spread across both campaign branches.\n\n1. Finish Mount Hyjal through Aessina's Miracle, then begin the Sanctuary of Malorne's Regrowth/Molten Front introduction. Enable Trivial Quests. Complete The Sanctuary Must Not Fall, collect 20 Marks of the World Tree for Calling for Reinforcements, and follow Through the Gates of Hell into the Molten Front. The portal is at 27.6,56.3 in Hyjal.\n\n2. At the Sanctuary of Malorne, speak to Matoclaw and Dorda'en Nightweaver. Select their available story dialogue, not just a quest hand-in. Do this while the early campaign dialogue is available; if Dorda'en later has no option, target him and try /talk, as reported in a later Retail comment.\n\n3. Inside Malfurion's Breach, speak to General Taldris Moonfall, Commander Jarod Shadowsong and Malfurion Stormrage. Look inside the cave/tree as well as immediately outside while scripted NPC movement finishes.\n\n4. Recruit Shadow Wardens and follow their Forlorn Spire route to speak with Deldren Ravenelm. Recruit Druids of the Talon and follow Into the Fire to speak with Thisalee Crow in the UNDERGROUND Molten Flow and Arthorn Windsong at the Furnace after exiting.\n\n5. Select the remaining conversations and check all eight names. The recruitment branches cost 150 marks EACH; choosing the first does not forbid the second. A conversation with another version of an NPC in a later expansion does not replace this campaign dialogue.",
        stepCount = 5,
        waypoints = {
            { mapID = 198, x = 0.271, y = 0.625, step = 1, label = "Sanctuary of Malorne - unlocks and daily quests" },
            { mapID = 198, x = 0.276, y = 0.624, step = 2, label = "Dorda'en / Matoclaw - Sanctuary dialogue" },
            { mapID = 338, x = 0.47, y = 0.907, step = 3, label = "Malfurion's Breach - three conversations" },
