    [5872] = {
        achievementId = 5872,
        name = "King of the Spider-Hill",
        category = "Quests",
        sourceType = "Achievement",
        source = "King of the Spider-Hill",
        difficulty = "medium",
        difficultyReason = "Climb by pulling spiders without killing them before their web-grab.",
        acquisition = "Difficulty: Medium - Climb by pulling spiders without killing them before their web-grab.\n\n1. Finish Mount Hyjal through Aessina's Miracle, then begin the Sanctuary of Malorne's Regrowth/Molten Front introduction. Enable Trivial Quests. Complete The Sanctuary Must Not Fall, collect 20 Marks of the World Tree for Calling for Reinforcements, and follow Through the Gates of Hell into the Molten Front. The portal is at 27.6,56.3 in Hyjal.\n\n2. Reach the tallest pillar formation in the Widow's Clutch around 65,56 in the Molten Front. Find a chain of Cinderweb Spinners on ledges that climbs toward its summit.\n\n3. Dismiss attacking pets and avoid damage procs. Aggro a spider on the next ledge with a harmless taunt or ranged interrupt; a high-level damage spell can kill it before it pulls you up. For classes without a suitable ability, later Retail comments describe low-damage Rough Dynamite or Fruit Basket as alternatives.\n\n4. Let its web-grab pull you onto its ledge, then kill that spider so it cannot drag you backward. Find the next higher spider in line of sight and repeat. Move around the pillar when a ledge blocks line of sight.\n\n5. Reach the VERY TOP and wait for credit; the second-highest ledge may not count. If a quest follower kills the spiders before they can pull, finish or set aside that follower quest before trying again.",
        stepCount = 5,
        waypoints = {
            { mapID = 198, x = 0.276, y = 0.563, step = 1, label = "Portal to Molten Front" },
            { mapID = 338, x = 0.65, y = 0.56, step = 2, label = "Widow's Clutch - highest spider pillar" },
        },
