    [5874] = {
        achievementId = 5874,
        name = "Death From Above",
        category = "Quests",
        sourceType = "Achievement",
        source = "Death From Above",
        difficulty = "hard",
        difficultyReason = "Two groups of bombing targets rotate; repeated daily access can take weeks.",
        acquisition = "Difficulty: Hard - Two groups of bombing targets rotate; repeated daily access can take weeks.\n\n1. Finish Mount Hyjal through Aessina's Miracle, then begin the Sanctuary of Malorne's Regrowth/Molten Front introduction. Enable Trivial Quests. Complete The Sanctuary Must Not Fall, collect 20 Marks of the World Tree for Calling for Reinforcements, and follow Through the Gates of Hell into the Molten Front. The portal is at 27.6,56.3 in Hyjal.\n\n2. Recruit the Druids of the Talon for 150 Marks of the World Tree. On their daily route, finish the base quests and escort the druid through Into the Fire into the underground Molten Flow. Follow the tunnel and its exit to the Furnace. Recruiting the Shadow Wardens alone does not open this route.\n\n3. At the Furnace, accept Fire in the Skies when offered and board the quest firehawk. This is the vehicle bombing flight, not ordinary flight through the Firelands raid. Keep the achievement tracked and inspect the six required names.\n\n4. During the flight, use the large ground-targeted bomb to HIT each available named elemental. A hit awards the criterion: they do NOT need to die. Ragepyre stands on a bare hill to the right leaving the spider area; Flashfire is partly hidden in the right-hand hills; Heatflayer is in the western spider area.\n\n5. Look left on the return approach for Blazefury, left atop a pillar for Hatespark, and left leaving the spider area for Singeslayer. Use /target with a missing name to help locate it, then aim an actual bomb. A target macro alone awards no credit.\n\n6. Only THREE of the six are present on a day's route. After bombing those three, check later daily rotations for the other group. Do not spend the flight searching for all six at once.\n\n7. To attempt another day with a retained quest, leave its ordinary kill objectives INCOMPLETE so the bird remains usable. Later replies confirm successes, but also report days when access requires doing the Talon daily chain again. If boarding is unavailable, finish the daily route when Fire in the Skies returns. Verify all six hits before the final hand-in.",
        stepCount = 7,
        waypoints = {
            { mapID = 198, x = 0.271, y = 0.625, step = 1, label = "Sanctuary of Malorne - unlocks and daily quests" },
            { mapID = 338, x = 0.47, y = 0.907, step = 2, label = "Malfurion's Breach - campaign hub" },
        },
        areaMaps = { 338 },
        sources = {
            "https://www.wowhead.com/achievement=5874#comments:id=1465128",
            "https://www.wowhead.com/achievement=5874#comments:id=1662500",
            "https://www.wowhead.com/achievement=5874#comments:id=5701475",
            "https://www.wowhead.com/achievement=5874#comments:id=6005783",
            "https://www.wowhead.com/achievement=5874#comments:id=6122524",
        },
        reviewedAt = "2026-11-10",
        wowheadUrl = "https://www.wowhead.com/achievement=5874",
        sourceURL = "https://www.wowhead.com/achievement=5874#comments",
    },
    [5875] = {
        description = "An account-wide collection milestone. The reward is added to the Pet Journal, rather than requiring a visit to a reward NPC.",
        acquisition = "Difficulty: Medium - No difficult fight is required, but collecting 150 different species takes travel and a growing collection.\n\n1. Open Littlest Pet Shop in Pet Battles > Collect and check its unique-species counter. Learn unused pet items and cages already in your bags before spending more gold; duplicates do not close the gap to 150.\n\n2. Buy missing vendor species. For example, Breanni in Northrend Dalaran at 58.6,39.6 sells Obsidian Hatchling, Albino Snake and Calico Cat. Alliance can also visit Donni Anthania at 44.2,53.2 in Elwynn Forest for the cheap house-cat varieties. Learn only species your account is missing.\n\n3. Train Battle Pet Training if necessary and capture missing wild species. Begin with low-level pets in Elwynn Forest (Alliance) or Durotar (Horde), then visit additional zones rather than repeatedly catching the same species. Reduce a wild pet below the trap's health threshold, use Trap, and win the encounter.\n\n4. Continue with inexpensive missing cages and guaranteed quest pets until you reach 150. The game adds Celestial Dragon to your Pet Journal automatically. Clear journal filters and relog if the achievement has completed but the pet is not yet visible; do not wait for an old-style Breanni reward letter.",
        stepCount = 4,
        waypoints = {
            {
                mapID = 125,
                x = 0.586,
                y = 0.396,
                step = 2,
                label = "Breanni - three vendor species, Northrend Dalaran",
                mapName = "Dalaran (Northrend)",
            },
            {
                mapID = 37,
                x = 0.442,
                y = 0.532,
                step = 2,
                label = "Donni Anthania - Alliance house-cat vendor",
                mapName = "Elwynn Forest",
