    [5879] = {
        achievementId = 5879,
        name = "Veteran of the Molten Front",
        category = "Quests",
        sourceType = "Achievement",
        source = "Veteran of the Molten Front",
        difficulty = "hard",
        difficultyReason = "Combines the full campaign, rotating daily mechanics and other-player requirements.",
        acquisition = "Difficulty: Hard - Combines the full campaign, rotating daily mechanics and other-player requirements.\n\n1. Track this meta and begin The Molten Front Offensive. Finish the Hyjal prerequisite and the 20-mark introduction, then earn both 150-mark recruitments and all three 125-mark support projects. Keep one character's campaign moving; unlocks themselves are not automatically shared across the Warband.\n\n2. During Hyjal's daily circuit, complete Legacy of Leyara, Fiery Lords, Ludicrous Speed, Gang War, Have... Have We Met?, And the Meek Shall Inherit Kalimdor and Infernal Ambassadors. Read each individual guide before its relevant daily; several conditions cannot be recovered after turning the quest in.\n\n3. Inside the Front, complete Flawless Victory, Fireside Chat, Master of the Molten Flow, King of the Spider-Hill, Ready for Raiding II and Death From Above. Prioritize unlocking Talon access early enough to start the bombing rotation while earning later campaign marks.\n\n4. Arrange a duel partner for Gang War and an opposite-faction helper/eligible alt for Mankrik or Thassarian. Check the actual criteria to combine eligible Warband progress rather than assuming an alt has the same quest unlocks.\n\n5. Return for missing daily variants, visitor names, bombing groups and lieutenants until EVERY component is checked. Random repeats prevent a guaranteed finish date. This meta awards the Flamebreaker title; the Offensive component separately awards the Flameward Hippogryph.",
        stepCount = 5,
        waypoints = {
            { mapID = 198, x = 0.271, y = 0.625, step = 1, label = "Sanctuary of Malorne - unlocks and daily quests" },
            { mapID = 338, x = 0.47, y = 0.907, step = 2, label = "Malfurion's Breach - campaign hub" },
        },
        sources = {
            "https://www.wowhead.com/achievement=5879#comments:id=1465622",
