    [6045] = {
        achievementId = 6045,
        name = "Occu'thar",
        category = "Raids",
        sourceType = "Achievement",
        source = "Occu'thar",
        difficulty = "easy",
        difficultyReason = "A short legacy raid kill once your faction has Tol Barad access.",
        acquisition = "Difficulty: Easy - A short legacy raid kill once your faction has Tol Barad access.\n\n1. Travel to Tol Barad and check which faction controls it. Baradin Hold is accessible to the controlling faction; if necessary, queue for the next Tol Barad battle and win control before attempting the raid entrance at 47.5,39.0.\n\n2. Enter Baradin Hold and take the wing marked for Occu'thar. Clear the approach and defeat that named boss. The other two bosses have separate achievements, so killing whichever one is nearest does not replace this target.\n\n3. Confirm Occu'thar is credited and loot the boss before leaving. These are raid boss kills despite their catalogue placement beside Tol Barad PvP achievements; the zone battle alone does not award them.",
        stepCount = 3,
        waypoints = {
            {
                mapID = 244,
                x = 0.475,
